const RawLogAttachment = z.object({
	type: z.literal('text').describe('type of attachment'),
	view_type: z
		.literal('inline')
		.describe('inline means open in new browser tab'),
	name: z.string().describe('name of attachment'),
	description: z
		.string()
		.optional()
		.describe('optional description of attachment'),
	download_enabled: z
		.boolean()
		.optional()
		.default(false)
		.describe('should show button to download attachment'),
	path: z
		.string()
		.optional()
		.describe('path of attachment relative to attachments.json'),
	uri: z
		.string()
		.optional()
		.describe(
			'uri of attachment, if it is not relative to attachments.json or external'
		)
});

const PacketCaptureAttachment = z.object({
	type: z.literal('packet-capture').describe('type of attachment'),
	view_type: z
		.literal('bublik-tools/net-packet-analyzer')
		.describe('view with network packet analyzer tool'),
	name: z.string().describe('name of attachment'),
	description: z
		.string()
		.optional()
		.describe('optional description of attachment'),
	download_enabled: z
		.boolean()
		.optional()
		.default(false)
		.describe('should show button to download attachment'),
	path: z
		.string()
		.optional()
		.describe('path of attachment relative to attachments.json'),
	uri: z
		.string()
		.optional()
		.describe(
			'uri of attachment, if it is not relative to attachments.json or external'
		)
});

const LogAttachments = z.discriminatedUnion('type', [
	RawLogAttachment,
	PacketCaptureAttachment
]);

export type LogAttachmentType = z.infer<typeof LogAttachments>['type'];

export type GetLogAttachmentByType<T extends LogAttachmentType> = Extract<
	z.infer<typeof LogAttachments>,
	{ type: T }
>;

const AttachmentsSchema = z
	.object({
		version: z.number().describe('version of attachments.json'),
		attachments: z.array(LogAttachments).describe('list of attachments')
	})
	.describe('attachments.json schema');

type AttachmentsJsonResponse = {
	attachments_base_url: string;
	data: z.infer<typeof AttachmentsSchema>;
};

function getAttachmentsBaseUrl(attachmentsUrl: string): string {
	try {
		const url = new URL(attachmentsUrl);

		if (url.pathname.includes('/proxy/')) {
			const originalUrl = new URL(url.searchParams.get('url') || '');
			return originalUrl.href.replace(/\/attachments\.json$/, '');
		}

		return attachmentsUrl.replace(/\/attachments\.json$/, '');
	} catch (e) {
		return attachmentsUrl;
	}
}

type LogUrlResponse = {
	url: string;
	attachments_url: string;
};

export const normalizeLogJsonInput = (
	input: GetLogJsonInputs
): GetLogJsonInputs => {
	const page = input.page ?? undefined;

	return typeof page === 'undefined'
		? { id: input.id }
		: { id: input.id, page };
};

export const constructJsonUrl = (input: GetLogJsonInputs): string => {
	const PREFIX = '/api/v2';

	if (input.page == null) return `${PREFIX}/logs/${input.id}/json/`;

	return `${PREFIX}/logs/${input.id}/json/?page=${input.page}`;
};

const LOG_JSON_RETRY_DELAYS_MS = [250, 1000] as const;

const isRetryableLogStatus = (status: number): boolean =>
	status === 404 ||
	status === 408 ||
	status === 425 ||
	status === 429 ||
	status >= 500;

const waitForLogRetry = (
	delay: number,
	signal?: AbortSignal
): Promise<void> => {
	if (signal?.aborted) {
		return Promise.reject(
			signal.reason ??
				new DOMException('The operation was aborted', 'AbortError')
		);
	}

	return new Promise((resolve, reject) => {
		const onAbort = () => {
			clearTimeout(timeoutId);
			reject(
				signal?.reason ??
					new DOMException('The operation was aborted', 'AbortError')
			);
		};
		const timeoutId = setTimeout(() => {
			signal?.removeEventListener('abort', onAbort);
			resolve();
		}, delay);

		signal?.addEventListener('abort', onAbort, { once: true });
	});
};

/**
 * The backend returns absolute log URLs pointing at the log server, which is a
 * different origin from the Vite dev server and fails CORS. In development
 * route them through the dev server's `/external` proxy instead.
 */
const toFetchableLogUrl = (url: string): string => {
	if (!config.isDev) return url;

	try {
		if (new URL(url).origin === window.location.origin) return url;
	} catch {
		// Relative URL, already same-origin
		return url;
	}

	return `${config.rootUrl}/external?url=${encodeURIComponent(url)}`;
};

export const fetchJson = async <T = unknown>(
	externalUrl: string,
	signal?: AbortSignal
): Promise<T> => {
	const getBublikFromStatusCode = (response: Response): BublikHttpError => {
		return { status: response.status, data: response.statusText };
	};

	const options: RequestInit = {
		credentials: 'include',
		cache: 'no-store',
		referrerPolicy: 'origin',
		signal
	};

	const url = toFetchableLogUrl(externalUrl);

	for (let attempt = 0; attempt <= LOG_JSON_RETRY_DELAYS_MS.length; attempt++) {
		try {
			const response = await fetch(url, options);

			if (!response.ok) {
				const error = getBublikFromStatusCode(response);
				const retryDelay = LOG_JSON_RETRY_DELAYS_MS[attempt];

				if (
					!isRetryableLogStatus(response.status) ||
					retryDelay === undefined
				) {
					throw error;
				}

				await waitForLogRetry(retryDelay, signal);
				continue;
			}

			return await response.json();
		} catch (error) {
			if (signal?.aborted) throw signal.reason ?? error;
			if (!(error instanceof SyntaxError) && !(error instanceof TypeError)) {
				throw error;
			}

			const retryDelay = LOG_JSON_RETRY_DELAYS_MS[attempt];
			if (retryDelay === undefined) {
				if (error instanceof TypeError) throw error;

				const generationError: BublikError = {
					status: 503,
					title: 'Log is not ready',
					description:
						'Log generation did not complete. Please retry in a moment.'
				};

				throw generationError;
			}

			await waitForLogRetry(retryDelay, signal);
		}
	}

	throw new Error('Log JSON retry loop finished unexpectedly');
};

async function fetchPagesCount(
	id: string | number | null | undefined,
	api: BaseQueryApi,
	baseQuery: (
		arg: Parameters<BublikBaseQueryFn>[0]
	) => ReturnType<BublikBaseQueryFn>
): Promise<number | undefined> {
	if (id === null || id === undefined) return undefined;

	try {
		const jsonUrl = (await baseQuery(
			constructJsonUrl({ id })
		)) as QueryReturnValue<LogUrlResponse>;

		if (jsonUrl.error || !jsonUrl.data) return undefined;

		const firstPage = await fetchJson<RootBlock>(jsonUrl.data.url, api.signal);

		return firstPage.root.find((b) => b.type === 'te-log')?.pagination
			?.pages_count;
	} catch (e) {
		console.error(e);

		return undefined;
	}
}

export const logEndpoints = {
	endpoints: (
		build: EndpointBuilder<BublikBaseQueryFn, BUBLIK_TAG, API_REDUCER_PATH>
	) => ({
		getTreeByRunId: build.query<TreeDataAPIResponse | null, string>({
			query: (runId) => ({
				url: withApiV2(`/tree/${runId}`),
				cache: 'no-cache'
			}),
			transformResponse: transformLogTree,
			providesTags: configDependent(BUBLIK_TAG.LogData)
		}),
		getLogUrlByResultId: build.query<ResultLogAPIResponse, number>({
			// The log base URL comes from `per_conf`, so this has to refetch on
			// a config change. `cache: 'no-cache'` because the server stamps
			// `Cache-Control: max-age=600` on API GETs.
			query: (resultId) => ({
				url: withApiV2(`/logs/${resultId}/html`),
				cache: 'no-cache'
			}),
			providesTags: configDependent(BUBLIK_TAG.LogData)
		}),
		getLogAttachments: build.query<AttachmentsJsonResponse, number>({
			queryFn: async (id, _api, _extraOptions, baseQuery) => {
				try {
					const getUrl = constructJsonUrl({ id });

					const jsonUrl = (await baseQuery(
						getUrl
					)) as QueryReturnValue<LogUrlResponse>;

					if (jsonUrl.error) {
						return {
							error: {
								status: 400,
								title: 'Something went wrong',
								description:
									'We are not sure what exactly went wrong, please report'
							}
						};
					}

					if (!jsonUrl.data) {
						return {
							error: {
								status: 404,
								title: 'No data',
								description: 'No json data found in response'
							}
						};
					}

					const attachmentsJson = await fetchJson<
						z.infer<typeof AttachmentsSchema>
					>(jsonUrl.data.attachments_url);

					return {
						data: {
							attachments_base_url: getAttachmentsBaseUrl(
								jsonUrl.data.attachments_url
							),
							data: attachmentsJson
						}
					};
				} catch (e) {
					console.error(e);

					const defaultError: BublikError = {
						status: 400,
						title: 'Something went wrong',
						description:
							'We are not sure what exactly went wrong, please report'
					};

					if (isBublikParsableError(e)) return { error: e };

					return { error: defaultError };
				}
			},
			providesTags: configDependent(BUBLIK_TAG.LogData)
		}),
		getLogJson: build.query<RootBlock, GetLogJsonInputs>({
			serializeQueryArgs: ({ queryArgs }) => normalizeLogJsonInput(queryArgs),
			queryFn: async (input, api, _extraOptions, baseQuery) => {
				const { page, id } = normalizeLogJsonInput(input);
				const getUrl = constructJsonUrl({ page, id });

				const jsonUrl = (await baseQuery(
					getUrl
				)) as QueryReturnValue<LogUrlResponse>;

				if (jsonUrl.error) throw jsonUrl.error;

				if (!jsonUrl.data) {
					// eslint-disable-next-line no-throw-literal
					throw {
						status: 404,
						title: 'No data',
						description: 'No json data found in response'
					};
				}

				try {
					const [blocksJson, artifactsAndVerdicts] = (await Promise.all([
						fetchJson<RootBlock>(jsonUrl.data.url, api.signal),
						baseQuery(withApiV2(`/results/${id}/artifacts_and_verdicts`))
					])) as [RootBlock, QueryReturnValue<ResultsAndVerdictsForIteration>];

					if (artifactsAndVerdicts.error) {
						console.error(artifactsAndVerdicts.error);
					}

					const blocksWithAddedVerdictsAndArtifacts = artifactsAndVerdicts.data
						? addArtifactsVerdicts(blocksJson, artifactsAndVerdicts.data)
						: blocksJson;

					const result = await fixPagesCountForAllView(
						blocksWithAddedVerdictsAndArtifacts,
						id,
						api,
						() => fetchPagesCount(id, api, baseQuery)
					);

					return { data: result };
				} catch (e) {
					console.error(e);

					const defaultError: BublikError = {
						status: 400,
						title: 'Something went wrong',
						description:
							'We are not sure what exactly went wrong, please report'
					};

					if (isBublikParsableError(e)) return { error: e };

					return { error: defaultError };
				}
			},
			// Deliberately not `configDependent`: this is the largest payload in
			// the app and its body is raw TE log content, which no config can
			// reshape. Dropping it on every config save would re-download the
			// whole log for nothing.
			providesTags: [BUBLIK_TAG.LogData]
		})
	})
};

function addArtifactsVerdicts(
	logBlocks: RootBlock,
	artifactsAndVerdicts: ResultsAndVerdictsForIteration
): RootBlock {
	return createNextState(logBlocks, (s) => {
		const teLog = s.root.find((b) => b.type === 'te-log');
		if (!teLog) return;

		const logMeta = teLog.content.find((b) => b.type === 'te-log-meta');
		if (!logMeta) return;

		if (artifactsAndVerdicts.verdicts.length) {
			logMeta.meta.verdicts = artifactsAndVerdicts.verdicts.map((v) => ({
				level: 'RING', // default to this level since level is not provided by API
				verdict: v.value
			}));
		}

		if (artifactsAndVerdicts.artifacts.length) {
			logMeta.meta.artifacts = artifactsAndVerdicts.artifacts.map((v) => ({
				level: 'RING', // default to this level since level is not provided by API
				artifact: v.value
			}));
		}
	});
}

export function cachedPagesCount(
	id: string | number | null | undefined,
	api: BaseQueryApi
): number | undefined {
	const state = api.getState() as {
		bublikApi?: {
			queries?: Record<
				string,
				{ originalArgs?: GetLogJsonInputs; data?: RootBlock }
			>;
		};
	};
	const queries = state?.bublikApi?.queries ?? {};

	for (const key of Object.keys(queries)) {
		if (!key.startsWith('getLogJson')) continue;

		const cached = queries[key];
		if (String(cached?.originalArgs?.id) !== String(id)) continue;

		// Only page=0 is the all-pages view. An omitted page is the canonical
		// first page and can provide the page count.
		const cachedPage = cached.originalArgs?.page;
		if (cachedPage === 0 || cachedPage === '0') continue;

		const cachedTeLog = cached.data?.root.find((b) => b.type === 'te-log');
		if (
			cachedTeLog?.pagination?.pages_count &&
			cachedTeLog.pagination.pages_count > 0
		) {
			return cachedTeLog.pagination.pages_count;
		}
	}

	return undefined;
}

export async function fixPagesCountForAllView(
	logBlocks: RootBlock,
	id: string | number | null | undefined,
	api: BaseQueryApi,
	readPagesCount: () => Promise<number | undefined>
): Promise<RootBlock> {
	const teLog = logBlocks.root.find((b) => b.type === 'te-log');

	// Only fix when pages_count is 0 (ALL PAGES)
	if (!teLog?.pagination || teLog.pagination.pages_count !== 0) {
		return logBlocks;
	}

	const pagesCount = cachedPagesCount(id, api) ?? (await readPagesCount());

	if (!pagesCount || pagesCount <= 0) return logBlocks;

	return createNextState(logBlocks, (draft) => {
		const teLogDraft = draft.root.find((b) => b.type === 'te-log');
		if (teLogDraft?.pagination) {
			teLogDraft.pagination.pages_count = pagesCount;
		}
	});
}
