import { EndpointBuilder } from '@reduxjs/toolkit/query';

import {
	RunsAPIResponse,
	RunsAPIQuery,
	RunsChartsAPIQuery,
	RunsChartsAPIResponse,
	RunsChartsAPIQuerySchema,
	RunsChartsAPIResponseSchema
} from '@/shared/types';

import { prepareForSend } from '../utils';
import { BUBLIK_TAG } from '../types';
import { configDependent } from '../tags';
import { BublikBaseQueryFn, withApiV2 } from '../config';
import { API_REDUCER_PATH } from '../constants';

const RUNS_PROGRESS_PAGE_SIZE = 50;

const getRunsProgressNextPageParam = (
	lastPage: RunsAPIResponse,
	lastPageParam: number
): number | undefined =>
	lastPage.pagination.next ? lastPageParam + 1 : undefined;

const getRunsTablePageParams = (queryParams: RunsAPIQuery) => {
	const { projects, runData, ...rest } = queryParams;

	return {
		...prepareForSend(rest),
		project: projects?.[0],
		...(runData !== undefined ? { run_metas: runData } : {})
	};
};

const getRunsChartsParams = (queryParams: RunsChartsAPIQuery) => {
	const { projects, runData, ...rest } = queryParams;

	return {
		...prepareForSend(rest),
		project: projects?.[0],
		...(runData !== undefined ? { run_metas: runData } : {})
	};
};

export const runsEndpoints = {
	endpoints: (
		build: EndpointBuilder<BublikBaseQueryFn, BUBLIK_TAG, API_REDUCER_PATH>
	) => ({
		getRunsTablePage: build.query<RunsAPIResponse, RunsAPIQuery>({
			query: (queryParams) => {
				return {
					url: withApiV2('/runs'),
					params: getRunsTablePageParams(queryParams),
					cache: 'no-cache'
				};
			},
			providesTags: configDependent(BUBLIK_TAG.Run, BUBLIK_TAG.SessionList)
		}),
		getRunsProgress: build.infiniteQuery<RunsAPIResponse, RunsAPIQuery, number>(
			{
				infiniteQueryOptions: {
					initialPageParam: 1,
					getNextPageParam: (lastPage, _allPages, lastPageParam) =>
						getRunsProgressNextPageParam(lastPage, lastPageParam)
				},
				query: ({ queryArg, pageParam }) => ({
					url: withApiV2('/runs'),
					params: getRunsTablePageParams({
						...queryArg,
						page: pageParam.toString(),
						pageSize: RUNS_PROGRESS_PAGE_SIZE.toString()
					}),
					cache: 'no-cache'
				}),
				providesTags: configDependent(BUBLIK_TAG.Run, BUBLIK_TAG.SessionList)
			}
		),
		getRunsCharts: build.query<RunsChartsAPIResponse, RunsChartsAPIQuery>({
			query: (queryParams) => {
				return {
					url: withApiV2('/runs/charts'),
					params: getRunsChartsParams(queryParams),
					cache: 'no-cache'
				};
			},
			argSchema: RunsChartsAPIQuerySchema,
			responseSchema: RunsChartsAPIResponseSchema,
			providesTags: configDependent(BUBLIK_TAG.Run, BUBLIK_TAG.SessionList)
		})
	})
};

export {
	RUNS_PROGRESS_PAGE_SIZE,
	getRunsProgressNextPageParam,
	getRunsTablePageParams,
	getRunsChartsParams
};
